items.body:
### Your current environment

PD 分离部署 GLM5.2-w8a8（稀疏注意力，带 IndexShare），Prefill 节点关闭 DCP，仅 Decode 节点开启 DCP 时，推理输出乱码、token 重复、语义错乱，存在精度问题。


### 🐛 Describe the bug

export MODEL_PATH="/data/GLM-5.2-w8a8c8"

nic_name="enp66s0f1"
local_ip="$(ifconfig enp66s0f1 2>/dev/null | grep "inet " | awk '{print $2}')"
echo "-----------------$local_ip---------------------"


export HCCL_IF_IP=$local_ip
export GLOO_SOCKET_IFNAME=$nic_name
export TP_SOCKET_IFNAME=$nic_name
export HCCL_SOCKET_IFNAME=$nic_name
export VLLM_HOST_IP=$local_ip


export OMP_PROC_BIND=false
export OMP_NUM_THREADS=10
export PYTORCH_NPU_ALLOC_CONF=expandable_segments:True
export VLLM_ASCEND_ENABLE_MLAPO=1
export HCCL_BUFFSIZE=2560
export TASK_QUEUE_ENABLE=1
export HCCL_OP_EXPANSION_MODE="AIV"


export ASCEND_RT_VISIBLE_DEVICES=$1
export LD_LIBRARY_PATH=/usr/local/lib:$LD_LIBRARY_PATH

export PYTHONHASHSEED=0
export MMC_LOCAL_CONFIG_PATH="$PWD/mmc-local.conf"
#export MOONCAKE_CONFIG_PATH="$PWD/mooncake.json"
#export HCCL_INTRA_ROCE_ENABLE=1

export ACL_OP_INIT_MODE=1
export ASCEND_A3_ENABLE=1


#export KV_PORT=$((30000 + ($4 % 4 + 2) * 100))
export KV_PORT=30200

#export ENGINE_ID=$(($4 % 4 + 2))

export ENGINE_ID=2
DNODE0=$(( $4 / 2 ))
if [ "$DNODE0" -eq 0 ];then
	server_role_args="--api-server-count 1"
else
	server_role_args="--headless"
fi

echo "-----data-parallel-rank=$4------"
mkdir -p /model/log_2_mmc

KV_CONFIG_V1='{
        "kv_connector": "MooncakeConnectorV1",
        "kv_role": "kv_consumer",
        "kv_port": "30100",
        "engine_id": "1",
        "kv_connector_extra_config": {
            "use_ascend_direct": true,
            "prefill": {"dp_size": 4, "tp_size": 8},
            "decode": { "dp_size": 8, "tp_size": 4}
        }
    }'

KV_CONFIG_MNC='{
    "kv_connector": "MultiConnector",
    "kv_role": "kv_consumer",
    "kv_load_failure_policy": "recompute",
    "kv_connector_extra_config": {
        "connectors": [
            {
                "kv_connector": "MooncakeConnectorV1",
                "kv_role": "kv_consumer",
                "kv_port": "30100",
                "kv_connector_extra_config": {
                    "prefill": {
                        "dp_size": 4,
                        "tp_size": 8
                    },
                    "decode": {
                        "dp_size": 8,
                        "tp_size": 4
                    }
                }
            },
            {
                "kv_connector": "AscendStoreConnector",
                "kv_role": "kv_consumer",
                "kv_connector_extra_config": {
                    "lookup_rpc_port":"0",
                    "load_async": true,
                    "backend": "mooncake"
                }
            }
        ]
    }
    }'

KV_CONFIG_MMC='{
    "kv_connector": "MultiConnector",
    "kv_role": "kv_consumer",
    "engine_id": "1",
    "kv_connector_extra_config": {
        "connectors": [
            {
                "kv_connector": "MooncakeConnectorV1",
                "kv_role": "kv_consumer",
                "kv_port": "30100",
                "kv_connector_extra_config": {
                    "prefill": {
                        "dp_size": 4,
                        "tp_size": 8
                    },
                    "decode": {
                        "dp_size": 8,
                        "tp_size": 4
                    }
                }
            },
            {
                "kv_connector": "AscendStoreConnector",
                "kv_role": "kv_consumer",
                "kv_connector_extra_config": {
                    "lookup_rpc_port":"2",
                    "backend": "memcache"
                }
            }
        ]
    }
    }'

KV_CONFIG_MMC_PP='{
    "kv_connector": "MultiConnector",
    "kv_role": "kv_consumer",
    "engine_id": "1",
    "kv_connector_extra_config": {
        "connectors": [
            {
                "kv_connector": "MooncakeConnectorV1",
                "kv_role": "kv_consumer",
                "kv_port": "30100",
                "kv_connector_extra_config": {
					"use_ascend_direct":true,
                    "prefill": {
                        "dp_size": 1,
						"pp_size": 4,
                        "tp_size": 8,
						"pp_layer_partition":"22,20,20,16"
                    },
                    "decode": {
                        "dp_size": 4,
                        "tp_size": 8
                    }
                }
            },
            {
                "kv_connector": "AscendStoreConnector",
                "kv_role": "kv_consumer",
                "kv_connector_extra_config": {
                    "lookup_rpc_port":"2",
                    "backend": "memcache"
                }
            }
        ]
    }
    }'

nohup vllm serve $MODEL_PATH \
    --host 0.0.0.0 \
    --port $2 \
    --data-parallel-size $3 \
    --data-parallel-rank $4 \
    --data-parallel-address $5 \
    --data-parallel-rpc-port $6 \
    --tensor-parallel-size $7 \
	--prefill-context-parallel-size 1 \
    --decode-context-parallel-size 8 \
    --cp-kv-cache-interleave-size 128 \
    --enable-expert-parallel \
    --enable-prefix-caching \
    --seed 1024 \
    --served-model-name glm-52 \
    --max-model-len 262144 \
    --max-num-batched-tokens 192 \
	$server_role_args \
	--async-scheduling \
    --trust-remote-code \
    --max-num-seqs 32 \
    --gpu-memory-utilization 0.92 \
    --safetensors-load-strategy 'prefetch' \
    --quantization ascend \
    --enable-auto-tool-choice \
    --tool-call-parser glm47 \
    --reasoning-parser glm45 \
    --kv-transfer-config "$KV_CONFIG_MMC_PP" \
    --compilation-config \
    '{
        "cudagraph_mode": "FULL_DECODE_ONLY"
    }' \
    --profiler-config \
    '{
        "profiler": "torch",
        "torch_profiler_dir": "/data/prof",
        "torch_profiler_with_stack": false
    }' \
    --additional-config '{"enable_flashcomm1": false, "enable_dsa_cp": false, "ascend_compilation_config": {"enable_npugraph_ex": true, "enable_static_kernel": false}, "fuse_muls_add": true, "multistream_overlap_shared_expert": true, "enable_mc2_hierarchy_comm": false, "enable_sparse_sfa_c8": true, "enable_sparse_li_c8": true, "enable_cpu_binding": true, "recompute_scheduler_enable": true}' \
    --speculative-config '{"num_speculative_tokens": 5, "method":"deepseek_mtp", "enforce_eager":true}' \
     2>&1 | tee /model/log_2_mmc/glm52_decode_${local_ip}_rank$4_$(date +%Y%m%d_%H%M).log > /dev/null &
